function generateBreadcrumbs(){let e=document.getElementById("breadcrumbs");if(!e)return;e.innerHTML="";let t="/mmenu",n=window.location.pathname.split("/").filter(e=>e.length>0);n=n.filter(e=>"index.php"!==e&&"mmenu"!==e);let a=document.querySelector("h1"),r=a?a.textContent:document.title,i=window.location.search?window.location.search.substring(1):null,l=t,p=document.createElement("li"),d=document.createElement("a");d.href=`${t}/mmenu.php${i&&"inactivity"!==i?`?${i}`:""}`,d.textContent="Home",p.appendChild(d);let c=document.createElement("span");c.setAttribute("aria-hidden","true"),c.setAttribute("data-symbol",">"),c.textContent=" > ",p.appendChild(c),e.appendChild(p),n.forEach((t,a)=>{let p=a===n.length-1,d=capitalizeFirstLetterOfEachWord(t.replace(/-/g," "));l+=`/${t}`;let c=document.createElement("li");if(p)c.textContent=r;else{let o=document.createElement("a");o.href=`${l}/index.php${i&&"inactivity"!==i?`?${i}`:""}`,o.textContent=d,c.appendChild(o);let h=document.createElement("span");h.setAttribute("aria-hidden","true"),h.setAttribute("data-symbol",">"),h.textContent=" > ",c.appendChild(h)}e.appendChild(c)})}function capitalizeFirstLetterOfEachWord(e){return e.replace(/\b\w/g,e=>e.toUpperCase())}window.onload=generateBreadcrumbs;